class Solution:
    def numberOfPermutations(self, n: int, requirements: list[list[int]]) -> int:
        MOD = 10**9 + 7
        req = {e: c for e, c in requirements}
        maxj = req[n - 1]
        dp = [0] * (maxj + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            nd = [0] * (maxj + 1)
            for j in range(maxj + 1):
                nd[j] = sum(dp[j - t] for t in range(min(i, j + 1))) % MOD
            dp = nd
            if i - 1 in req:
                c = req[i - 1]
                if c > maxj:
                    return 0
                nd = [0] * (maxj + 1)
                nd[c] = dp[c]
                dp = nd
        return dp[maxj]

