class Solution {
public:
    int numberOfPermutations(int n, vector<vector<int>>& requirements) {
        const int MOD = 1e9 + 7;
        unordered_map<int,int> req;
        for (auto& r : requirements) req[r[0]] = r[1];
        int maxj = req[n - 1];
        vector<long long> dp(maxj + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            vector<long long> nd(maxj + 1, 0);
            for (int j = 0; j <= maxj; j++) {
                long long s = 0;
                for (int t = 0; t <= min(i - 1, j); t++) s += dp[j - t];
                nd[j] = s % MOD;
            }
            dp = nd;
            if (req.count(i - 1)) {
                int c = req[i - 1];
                if (c > maxj) return 0;
                fill(dp.begin(), dp.end(), 0LL);
                dp[c] = nd[c];
            }
        }
        return dp[maxj];
    }
};

