class Solution {
    public int numberOfPermutations(int n, int[][] requirements) {
        final int MOD = 1_000_000_007;
        Map<Integer, Integer> req = new HashMap<>();
        for (int[] r : requirements) req.put(r[0], r[1]);
        int maxj = req.get(n - 1);
        long[] dp = new long[maxj + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            long[] nd = new long[maxj + 1];
            for (int j = 0; j <= maxj; j++) {
                long s = 0;
                for (int t = 0; t <= Math.min(i - 1, j); t++) s += dp[j - t];
                nd[j] = s % MOD;
            }
            dp = nd;
            if (req.containsKey(i - 1)) {
                int c = req.get(i - 1);
                if (c > maxj) return 0;
                Arrays.fill(dp, 0);
                dp[c] = nd[c];
            }
        }
        return (int) dp[maxj];
    }
}

